/**
 * The events a player took part in: medals earned and spent, and the relics each one unlocked.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readEventsFromSaveRoot
 * depends    src/save/access/values, src/save/catalogs/relics, src/save/events/relic-sets, src/save/events/types
 * used by    src/save/events/index
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { coerceSaveNumber, readSaveListItems } from '../access/values'
import { findRelicLabel } from '../catalogs/relics'
import { findEventRelicSet } from './relic-sets'
import type { EventRecordSaveRow, EventsSaveExtract } from './types'

function readRecord(raw: unknown, warnings: string[], index: number): EventRecordSaveRow | null {
  if (!raw || typeof raw !== 'object') {
    warnings.push(`eventRecords[${index}] is not a record.`)
    return null
  }
  const row = raw as Record<string, unknown>
  const name = typeof row.eventName === 'string' && row.eventName.trim() ? row.eventName : null
  const relicsUnlocked = readSaveListItems(row.relicsUnlocked)
    .map(value => coerceSaveNumber(value))
    .filter((value): value is number => value !== null)
  return {
    number: coerceSaveNumber(row.eventNumber),
    date: typeof row.date === 'string' ? row.date : null,
    name,
    medals: coerceSaveNumber(row.medals),
    medalsSpent: coerceSaveNumber(row.medalsSpent),
    relicsUnlocked,
    relics: relicsUnlocked.map(relicIndex => ({ index: relicIndex, label: findRelicLabel(relicIndex) })),
    event: findEventRelicSet(name)?.event ?? null,
  }
}

/** Event history, or null for a save with no event data. */
export function readEventsFromSaveRoot(root: Record<string, unknown> | null): EventsSaveExtract | null {
  if (!root || !['eventRecords', 'lastEventNumber'].some(key => key in root)) return null
  const warnings: string[] = []
  return {
    lastEventNumber: coerceSaveNumber(root.lastEventNumber),
    medalsCurrentEvent: coerceSaveNumber(root.totalMedalsCurrentEvent),
    records: readSaveListItems(root.eventRecords)
      .map((raw, index) => readRecord(raw, warnings, index))
      .filter((row): row is EventRecordSaveRow => row !== null),
    warnings,
  }
}
